import requests

url = "https://api.djelia.cloud/v1/models/transcribe"
headers = {
    "x-api-key": "YOUR_API_KEY",
    "Content-Type": "multipart/form-data"
}
files = {
    "file": open("audio_file.wav", "rb")
}
params = {
    "translate_to_french": True
}

response = requests.post(url, headers=headers, files=files, params=params)
if response.status_code == 200:
    print("Transcription:", response.json())
else:
    print("Failed to transcribe:", response.status_code, response.text)

import 'dart:convert';
import 'dart:io';
import 'package:http/http.dart' as http;

void main() async {
  final url = Uri.parse('https://api.djelia.cloud/v1/models/transcribe');
  final headers = {
    "x-api-key": "YOUR_API_KEY",
  };
  final queryParams = {'translate_to_french': 'true'};
  final file = http.MultipartFile.fromBytes(
    'file',
    File('audio_file.wav').readAsBytesSync(),
    filename: 'audio_file.wav',
  );

  final request = http.MultipartRequest('POST', url..replace(queryParameters: queryParams))
    ..headers.addAll(headers)
    ..files.add(file);

  final response = await request.send();

  if (response.statusCode == 200) {
    final body = await response.stream.bytesToString();
    print('Transcription: ${jsonDecode(body)}');
  } else {
    print('Failed to transcribe: ${response.statusCode}');
  }
}

