import requests

url = "https://api.djelia.cloud/v2/models/tts/stream"
headers = {
    "x-api-key": "YOUR_API_KEY",
    "Content-Type": "application/json"
}
payload = {
    "text": "Aw ni ce, i ka kene wa?",
    # Supported speaker names: "Moussa", "Sekou", "Seydou"
    "description": "Moussa speaks with a very clear voice and a friendly tone",
    "chunk_size": 0.5
}

# Stream the audio and save chunks
with open("output.wav", "wb") as f:
    response = requests.post(url, headers=headers, json=payload, stream=True)
    if response.status_code == 200:
        for chunk in response.iter_content(chunk_size=8192):
            if chunk:
                f.write(chunk)
        print("Audio saved as output.wav")
    else:
        print("Failed to generate audio:", response.status_code, response.text)

import 'dart:convert';
import 'dart:io';
import 'package:http/http.dart' as http;

void main() async {
  final url = Uri.parse('https://api.djelia.cloud/v2/models/tts/stream');
  final headers = {
    "x-api-key": "YOUR_API_KEY",
    "Content-Type": "application/json"
  };
  // Supported speaker names: "Moussa", "Sekou", "Seydou"
  final payload = {
    "text": "Aw ni ce, i ka kene wa?",
    "description": "Moussa speaks with a very clear voice and a friendly tone",
    "chunk_size": 0.5
  };

  final client = http.Client();
  final request = http.Request('POST', url)
    ..headers.addAll(headers)
    ..body = jsonEncode(payload);

  final response = await client.send(request);

  if (response.statusCode == 200) {
    final file = File('output.wav');
    final sink = file.openWrite();

    await for (final chunk in response.stream) {
      sink.add(chunk);
    }

    await sink.close();
    print("Audio saved as output.wav");
  } else {
    print("Failed to generate audio: ${response.statusCode}");
  }

  client.close();
}

